#!/usr/bin/env python3
"""Print the SHA-256 of each file."""
import argparse
import hashlib
import os
import signal
import sys


def digest(stream) -> str:
    sha = hashlib.sha256()
    for chunk in iter(lambda: stream.read(1 << 16), b""):
        sha.update(chunk)
    return sha.hexdigest()


def main() -> int:
    parser = argparse.ArgumentParser(
        prog="sha",
        description="Print the SHA-256 of each file.",
        epilog="example: sha *.tar.gz | sort",
    )
    parser.add_argument("files", nargs="+", help="files to hash, or - for stdin")
    parser.add_argument("--version", action="version", version="sha 1.0.0")
    args = parser.parse_args()
    # Write undecodable file names back out as the bytes the user passed.
    sys.stdout.reconfigure(errors="surrogateescape")
    sys.stderr.reconfigure(errors="surrogateescape")
    status = 0
    for name in args.files:
        try:
            if name == "-":
                value = digest(sys.stdin.buffer)
            else:
                with open(name, "rb") as stream:
                    value = digest(stream)
        except OSError as err:
            print(f"sha: {name}: {err.strerror}", file=sys.stderr)
            status = 1
            continue
        if "\\" in name or "\n" in name:
            escaped = name.replace("\\", "\\\\").replace("\n", "\\n")
            print(f"\\{value}  {escaped}")
        else:
            print(f"{value}  {name}")
    return status


if __name__ == "__main__":
    try:
        sys.exit(main())
    except BrokenPipeError:
        os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())
        sys.exit(1)
    except KeyboardInterrupt:
        signal.signal(signal.SIGINT, signal.SIG_DFL)
        os.kill(os.getpid(), signal.SIGINT)
